import { Routes, Route } from 'react-router-dom';
import "./App.css";
import "./styles/custom.scss"

import Home from "./pages/Home";
import About from "./pages/About";
import Proyects from "./pages/Proyects";

function App() {
  return (
	<>
    	<div className="container-fluid min-vh-100 px-3 px-md-5 px-lg-0 min-vh-100 bg-secondary pt-6">
      		<div className="mx-auto bg-primary shadow-lg border border-black" style={{ maxWidth: '800px', maxHeight: '80vh' }}>
				<Routes>
					<Route path="/" element={<Home />} />
					<Route path="/about" element={<About />} />
					<Route path="/proyects" element={<Proyects />} />
				</Routes>
		</div>
	  </div>
  	</>
  );
}

export default App;
